<?php
/** Current series workflow, normal-login HTTP; original workers and loopback supplier only. */
function runMarketDramaWorkflowHttp($f,string $api,string $peer,string $suffix,string &$token,string $image,int $text,array &$report): void
{
    $db=think\facade\Db::class;$t=$f->tenant;$u=$f->user;$script=dirname(__DIR__).'/market-generation-http.php';
    $check=fn($ok,$why)=>MarketWorkerFixture::check((bool)$ok,$why);
    $post=function($path,$p)use($api,$suffix,&$token){return dataHttp($api,'/api/app.'.$path.$suffix,$p,$token);};
    $get=function($path,$p)use($peer,$suffix,&$token){return dataHttp($peer,'/api/app.'.$path.$suffix.'&'.http_build_query($p),[],$token,'GET');};
    $pair=function($path,$p)use($api,$peer,$suffix,&$token,$check,$t,$u){
        $multi=curl_multi_init();$handles=[];foreach([$api,$peer]as$base){$c=curl_init($base.'/api/app.'.$path.$suffix);curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>json_encode($p),CURLOPT_HTTPHEADER=>['Content-Type: application/json','Host: private-media.example.test','token: '.$token],CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20]);curl_multi_add_handle($multi,$c);$handles[]=$c;}
        do{curl_multi_exec($multi,$active);if($active)curl_multi_select($multi,.01);}while($active);$rows=[];foreach($handles as$c){$rows[]=json_decode((string)curl_multi_getcontent($c),true);curl_multi_remove_handle($multi,$c);curl_close($c);}curl_multi_close($multi);
        $why='';if($path==='aigc_short_drama.canvas_agent/send'&&(($rows[0]['code']??0)!==1||($rows[1]['code']??0)!==1))try{$input=$p;unset($input['canvas_id'],$input['thread_id']);app\common\service\app\aigc_short_drama\canvas_agent\ConversationService::send($t,$u,(int)$p['canvas_id'],(int)$p['thread_id'],$input);}catch(Throwable $e){$why=get_class($e).': '.$e->getMessage().' at '.basename($e->getFile()).':'.$e->getLine();}
        $check(($rows[0]['code']??0)===1&&($rows[1]['code']??0)===1,'Workflow concurrent admission refused: '.json_encode($rows).' '.$why);return array_column($rows,'data');
    };
    $calls=fn()=>count(file($f->dir.'/deep-calls.jsonl')?:[])+count(file($f->dir.'/submissions.jsonl')?:[]);
    $cfg=['default_text_model_id'=>'market_text_'.$text,'canvas_agent'=>['enabled'=>true,'execution_enabled'=>true,'dialogue_engine'=>'legacy','workflow'=>['enabled'=>true]]];
    if(!$db::name('aigc_short_drama_config')->where('tenant_id',$t)->count())$db::name('aigc_short_drama_config')->insert(['tenant_id'=>$t,'status'=>1,'config_json'=>'{}','create_time'=>time(),'update_time'=>time()]);
    $db::name('aigc_short_drama_config')->where('tenant_id',$t)->update(['config_json'=>json_encode($cfg)]);
    $videoRow=$db::name('power_market_product')->where(['resource_type'=>'model','model_type'=>'video'])->find();$video='market_video_model:'.$videoRow['id'];
    $meta=json_decode($videoRow['source_payload'],true);$meta['market_metadata']['params_schema']['properties']['duration']['enum']=[1,5];$meta['market_metadata']['params_schema']['properties']['image_url']=['type'=>'string'];$meta['market_metadata']['material_capabilities']['modes'][]=['code'=>'image_to_video','method'=>'image_to_video','fields'=>[['field'=>'image_url','kind'=>'image','role'=>'first','required'=>true,'minimum'=>1,'maximum'=>1]]];$db::name('power_market_product')->where('id',$videoRow['id'])->update(['source_payload'=>json_encode($meta)]);
    $baseSku=$db::name('power_market_sku')->where('product_id',$videoRow['id'])->find();$locked=json_decode($baseSku['locked_params'],true);$locked['duration']=5;
    $sku=app\common\model\power\PowerMarketSku::create(['product_id'=>$videoRow['id'],'sku_key'=>$f->prefix.'workflow-5s','title'=>'Private five seconds','locked_params'=>$locked,'usage_unit'=>'per_call','usage_unit_size'=>1,'sale_points'=>1,'upstream_price'=>1,'sale_status'=>1,'status'=>1]);
    $canvas=$post('aigc_short_drama.canvas/create',['title'=>'Private full series workflow']);$c=(int)$canvas['id'];$thread=$post('aigc_short_drama.canvas_agent/createThread',['canvas_id'=>$c,'request_key'=>'full-workflow-thread-0001','title'=>'Private two episode workflow']);$scope=['canvas_id'=>$c,'thread_id'=>$thread['id']];
    $nodes=fn()=>json_decode($db::name('aigc_short_drama_canvas')->where('id',$c)->value('nodes_json'),true);
    $view=fn()=>$get('aigc_short_drama.canvas_agent/workflow',$scope);
    $waitRun=function($run)use($db,$check){MarketWorkerFixture::wait(fn()=>!in_array($db::name('aigc_short_drama_canvas_agent_run')->where('id',$run)->value('status'),['queued','running'],true),'Workflow run did not reach a terminal state',70);$row=$db::name('aigc_short_drama_canvas_agent_run')->where('id',$run)->find();$check($row['status']==='success','Workflow run failed: '.json_encode(array_intersect_key($row,array_flip(['status','error_code','error']))));};
    $pref=['generation_mode'=>'auto','image_model'=>$image,'video_model'=>$video];
    $body=$scope+['request_key'=>'full-workflow-intake-0001','content'=>'/short-drama Synthetic workflow，虚构人物小方在白色摄影棚走到标记，然后挥手。制作两集短剧。','base_revision'=>$canvas['graph_revision'],'selected_node_ids'=>[],'preferences'=>$pref];[$ack,$same]=$pair('aigc_short_drama.canvas_agent/send',$body);$check($ack===$same,'Intake duplicated run');
    $f->start($script,'fixture_drama_agent_runner','drama');$f->start($script,'fixture_drama_planning_runner','planning');$f->start($script,'');
    try{
        $waitRun($ack['run_id']);$v=$view();$check($v['workflow']['stage_state']['key']==='intake'&&count($nodes())===0,'Intake generated graph before confirmation');$report['intake_concurrent_one_run_no_graph']=true;
        $v=$post('aigc_short_drama.canvas_agent/answerWorkflow',$scope+['expected_revision'=>$v['workflow']['state_revision'],'slot'=>'intake_review','value'=>json_encode(['story_direction'=>'小方在白色摄影棚走到标记，然后挥手。','episode_count'=>'2集','episode_duration'=>'10秒','visual_style'=>'电影写实','aspect_ratio'=>'1:1'],JSON_UNESCAPED_UNICODE)]);$check($v['workflow']['stage_state']['key']==='story','Confirmed intake did not enter story');$report['owner_confirmed_current_intake_contract']=true;
        $stage=function($expected)use($view,$get,$scope,$pair,$waitRun,$db,$c,$check,&$report){$v=$view();$check($v['workflow']['stage_state']['key']===$expected&&$v['workflow']['stage_state']['status']==='ready','Stage not ready: '.json_encode($v['workflow']['stage_state']));$p=$scope+['request_key'=>'as:'.$c.':'.$scope['thread_id'].':'.$v['workflow']['state_revision'].':'.$expected,'workflow_auto'=>true,'content'=>app\common\service\app\aigc_short_drama\canvas_agent\ConversationWorkflow::autoStagePrompt($expected),'base_revision'=>(int)$db::name('aigc_short_drama_canvas')->where('id',$c)->value('graph_revision'),'selected_node_ids'=>[]];[$ack,$same]=$pair('aigc_short_drama.canvas_agent/send',$p);$check($ack===$same,'Stage concurrent submission duplicated');$waitRun($ack['run_id']);$report['last_completed_stage']=$expected;return $view();};
        foreach(['story','outline','episode']as$name){$v=$stage($name);$check($v['workflow']['stage_state']['status']==='awaiting_stage_confirmation','Text stage has no owner confirmation');$v=$post('aigc_short_drama.canvas_agent/confirmWorkflowStage',$scope+['expected_revision'=>$v['workflow']['state_revision']]);$report[$name.'_native_planning_confirm_and_graph']=true;}
        $v=$stage('art');$report['art_from_confirmed_episode_no_extra_text_generation']=true;
        $v=$stage('assets');$check($v['workflow']['stage_state']['status']==='awaiting_plan_confirmation'&&count($v['workflow']['image_plan']['nodes'])===2,'Subject/scene image plan missing');$before=$calls();$v=$post('aigc_short_drama.canvas_agent/confirmWorkflowPlan',$scope+['expected_revision'=>$v['workflow']['state_revision'],'plan_hash'=>$v['workflow']['plan_hash']]);
        MarketWorkerFixture::wait(fn()=>count(array_filter($nodes(),fn($n)=>($n['type']??'')==='image'&&($n['metadata']['status']??'')==='success'))===2,'Confirmed subject/scene images did not finish without page polling',80);$report['subject_scene_confirm_auto_generate_managed_results']=true;
        $v=$view();$v=$post('aigc_short_drama.canvas_agent/answerWorkflow',$scope+['expected_revision'=>$v['workflow']['state_revision'],'slot'=>'next_stage','value'=>'three_view']);$v=$stage('assets');$check(count($v['workflow']['image_plan']['nodes'])===1,'Character view plan missing');$v=$post('aigc_short_drama.canvas_agent/confirmWorkflowPlan',$scope+['expected_revision'=>$v['workflow']['state_revision'],'plan_hash'=>$v['workflow']['plan_hash']]);
        MarketWorkerFixture::wait(fn()=>count(array_filter($nodes(),fn($n)=>($n['metadata']['workflow_artifact']??'')==='three_view'&&($n['metadata']['status']??'')==='success'))===1,'Three-view did not finish',80);$report['three_view_owned_subject_reference_and_background_result']=true;
        $v=$view();$v=$post('aigc_short_drama.canvas_agent/answerWorkflow',$scope+['expected_revision'=>$v['workflow']['state_revision'],'slot'=>'next_stage','value'=>'continue']);$v=$stage('video_plan');$check($v['workflow']['stage_state']['status']==='awaiting_stage_confirmation','Storyboard table not reviewable');$v=$post('aigc_short_drama.canvas_agent/confirmWorkflowStage',$scope+['expected_revision'=>$v['workflow']['state_revision']]);$v=$stage('storyboard');$boards=array_values(array_filter($nodes(),fn($n)=>($n['metadata']['workflow_artifact']??'')==='storyboard'));$check(count($boards)===2&&count(array_filter($boards,fn($n)=>($n['metadata']['status']??'idle')==='idle'))===2,'Storyboard images were automatically submitted');$report['confirmed_storyboard_table_two_manual_image_nodes']=true;
        $report['phase']='storyboard_ready';
    }catch(Throwable $e){$report['private_run_states']=$db::name('aigc_short_drama_canvas_agent_run')->field('id,status,error')->select()->toArray();$report['private_planning_states']=$db::name('aigc_short_drama_script_task')->field('id,status,error')->select()->toArray();$report['private_planning_units']=$db::name('aigc_short_drama_planning_unit')->field('unit_key,status,error')->select()->toArray();throw $e;}
    finally{$f->stop('planning');$f->stop('drama');$f->stop();}
}
